/bin/bash -lc "node --input-type=module <<'EOF'
import { chromium } from '@playwright/test'
const browser = await chromium.launch({ headless: true })
const page = await browser.newPage()
const requests = []
page.on('request', request => {
  if (request.url().includes('/product')) requests.push({ url: request.url(), prefetch: request.headers()['next-router-prefetch'] ?? null, segment: request.headers()['next-router-segment-prefetch'] ?? null })
})
await page.goto('http://localhost:3000/')
await page.getByRole('link', { name: 'View Product' }).click()
await page.getByRole('heading', { name: 'Premium Widget' }).waitFor()
await page.getByText(/in stock/).waitFor()
console.log(JSON.stringify({ title: await page.getByRole('heading').textContent(), stock: await page.getByText(/in stock/).textContent(), requests }))
await browser.close()
EOF"

/bin/bash -lc "node --input-type=module <<'EOF'
import { chromium } from '@playwright/test'
const browser = await chromium.launch({ headless: true })
const page = await browser.newPage()
await page.route('**/product?*', async route => {
  if ("'!route.request().headers()['"'next-router-prefetch']) {
    await new Promise(resolve => setTimeout(resolve, 1200))
  }
  await route.continue()
})
const shellPrefetch = page.waitForResponse(response =>
  response.url().includes('/product?') &&
  response.request().headers()['next-router-segment-prefetch'] === '/product/__PAGE__'
)
await page.goto('http://localhost:3000/')
await shellPrefetch
await page.getByRole('link', { name: 'View Product' }).click()
await page.getByRole('heading', { name: 'Premium Widget' }).waitFor({ timeout: 600 })
const loadingShown = await page.getByText('Loading inventory...').isVisible()
await page.getByText(/in stock/).waitFor()
console.log(JSON.stringify({ loadingShownBeforeLiveResponse: loadingShown, inventoryLoaded: await page.getByText(/in stock/).textContent() }))
await browser.close()
EOF"
